(window.DP = window.DP || {}).L10N = window.DP.L10N || {};
window.DP.L10N["pl"] = {"ui":{"Velikost písma: {v}":"Rozmiar tekstu: {v}","Váš prohlížeč neumí číst nahlas.":"Twoja przeglądarka nie potrafi czytać na głos.","Zastavit čtení":"Zatrzymaj czytanie","Přečíst nahlas":"Przeczytaj na głos","Mluvit":"Mów","Poslouchám… klepněte pro konec":"Słucham… dotknij, aby zakończyć","Tento prohlížeč diktování neumí. Klepněte do pole a použijte mikrofon na klávesnici telefonu.":"Ta przeglądarka nie obsługuje dyktowania. Dotknij pola i użyj mikrofonu na klawiaturze telefonu.","Povolte prosím mikrofon pro tuto stránku v nastavení prohlížeče.":"Zezwól na mikrofon dla tej strony w ustawieniach przeglądarki.","Diktování je vypnuté. Na iPhonu zapněte Siri a diktování v Nastavení, nebo použijte mikrofon na klávesnici.":"Dyktowanie jest wyłączone. Na iPhonie włącz Siri i dyktowanie w Ustawieniach albo użyj mikrofonu na klawiaturze.","Nic jsem neslyšel. Klepněte na Mluvit a mluvte prosím blíž k telefonu.":"Nic nie usłyszałem. Dotknij Mów i mów bliżej telefonu.","Nenašel jsem mikrofon. Zkontrolujte, že ho nepoužívá jiná aplikace.":"Nie znalazłem mikrofonu. Sprawdź, czy nie używa go inna aplikacja.","Diktování potřebuje internet. Zkuste to znovu, nebo dotaz napište.":"Dyktowanie potrzebuje internetu. Spróbuj ponownie albo wpisz pytanie.","Diktování v tomto jazyce tu není dostupné. Použijte mikrofon na klávesnici.":"Dyktowanie w tym języku nie jest tu dostępne. Użyj mikrofonu na klawiaturze.","Zkontrolujte prosím text. Pokud sedí, stiskněte tlačítko pro odeslání.":"Sprawdź tekst. Jeśli się zgadza, naciśnij przycisk wysyłania.","Diktování se nepodařilo spustit. Zkuste to prosím znovu.":"Nie udało się uruchomić dyktowania. Spróbuj ponownie.","Zavolat":"Zadzwoń","Dobré ráno!":"Dzień dobry!","Dobrý večer!":"Dobry wieczór!","Dobrý den!":"Dzień dobry!","Napište prosím svůj dotaz.":"Wpisz swoje pytanie.","Napište, s čím potřebujete pomoct":"Napisz, w czym potrzebujesz pomocy","Zeptat se":"Zapytaj","Volá mi někdo z banky":"Dzwoni do mnie ktoś z banku","Přišla mi divná SMS o balíku":"Dostałem dziwnego SMS-a o paczce","Co je Facebook?":"Co to jest Facebook?","Jak poslat fotku vnoučatům?":"Jak wysłać zdjęcie wnukom?","Zapomněl/a jsem heslo":"Zapomniałem hasła","Telefon se rychle vybíjí":"Telefon szybko się rozładowuje","Váš vlídný průvodce":"Twój życzliwy przewodnik","S čím vám mohu dnes pomoci?":"W czym mogę dziś pomóc?","Technologie bez stresu, spěchu a obav. Vše vysvětlíme česky, pomalu a krok za krokem.":"Technologia bez stresu, pośpiechu i obaw. Wszystko wyjaśniamy powoli, krok po kroku.","Například: Jak poslat fotku?":"Na przykład: Jak wysłać zdjęcie?","Usměvavá paní s brýlemi drží chytrý telefon.":"Uśmiechnięta pani w okularach trzyma smartfon.","Bez obav":"Bez obaw","Technologie bez stresu":"Technologia bez stresu","Ptejte se snadno":"Pytaj śmiało","Žádná otázka není hloupá. Napište ji, nebo ji řekněte nahlas tlačítkem ":"Żadne pytanie nie jest głupie. Napisz je albo powiedz na głos przyciskiem ","Hlavní pomocníci":"Główni pomocnicy","Zeptejte se":"Zapytaj","Rozhovor s parťákem. Přednostně odpovídá ověřenými radami, jiné odpovědi jasně označí.":"Rozmowa z pomocnikiem. Najpierw odpowiada sprawdzonymi poradami, inne odpowiedzi wyraźnie oznacza.","Otevřít rozhovor":"Otwórz rozmowę","Žádná otázka není hloupá":"Żadne pytanie nie jest głupie","Je to podvod?":"Czy to oszustwo?","Přišla vám divná SMS nebo e-mail? Společně zkontrolujeme varovné znaky.":"Dostałeś dziwnego SMS-a lub e-mail? Razem sprawdzimy sygnały ostrzegawcze.","Zkontrolovat zprávu":"Sprawdź wiadomość","Text nikam neodesíláme":"Nigdzie nie wysyłamy Twojego tekstu","Krok za krokem":"Krok po kroku","Jednoduché návody. Vždy jen jeden krok na obrazovce.":"Proste poradniki. Zawsze tylko jeden krok na ekranie.","Prohlédnout návody":"Zobacz poradniki","Pomalu, jak vám vyhovuje":"W Twoim tempie","Časté otázky":"Częste pytania","Klepněte a hned dostanete odpověď.":"Dotknij, a od razu dostaniesz odpowiedź.","Vaše bezpečí je na 1. místě":"Twoje bezpieczeństwo jest najważniejsze","Nikdy po vás nechceme hesla, PIN ani číslo karty.":"Nigdy nie prosimy o hasła, PIN ani numer karty.","Parťák odpovídá z knihovny ověřených rad. Každou jinou odpověď jasně označí, abyste si ji mohli ověřit.":"Pomocnik odpowiada z biblioteki sprawdzonych porad. Każdą inną odpowiedź wyraźnie oznacza, abyś mógł ją sprawdzić.","Vaše dotazy zůstávají jen ve vašem zařízení.":"Twoje pytania pozostają tylko na Twoim urządzeniu.","Usměvavý pán s brýlemi pracuje na tabletu.":"Uśmiechnięty pan w okularach korzysta z tabletu.","Chcete mluvit s člověkem?":"Chcesz porozmawiać z człowiekiem?","Senior telefon je zdarma a nonstop.":"Senior telefon (czeska infolinia dla seniorów) jest bezpłatny i całodobowy.","Další čísla pomoci":"Inne numery pomocy","Přizpůsobit aplikaci":"Dostosuj aplikację","Velikost písma, vysoký kontrast, čtení nahlas":"Rozmiar tekstu, wysoki kontrast, czytanie na głos","Rozhovor s DIGI parťákem":"Rozmowa z DIGI parťákiem","Napište svůj dotaz…":"Wpisz swoje pytanie…","Zeptejte se parťáka":"Zapytaj pomocnika","Ověřené rady mají zelený štítek":"Sprawdzone porady mają zieloną etykietę","Rozhovor jsem smazal.":"Usunąłem rozmowę.","Nový rozhovor":"Nowa rozmowa","Do chatu nikdy nepište hesla, PIN ani číslo karty. Rozhovor se neukládá a po zavření aplikace zmizí.":"Nigdy nie wpisuj do czatu haseł, PIN-u ani numeru karty. Rozmowa nie jest zapisywana i znika po zamknięciu aplikacji.","Váš dotaz":"Twoje pytanie","Odeslat":"Wyślij","Myslíte jedno z těchto témat?":"Czy chodzi o jeden z tych tematów?","Promiňte, nerozuměl jsem.":"Przepraszam, nie zrozumiałem.","Promiňte, na tohle teď nemám odpověď.":"Przepraszam, nie mam teraz na to odpowiedzi.","V aplikaci to nemám, hledám odpověď mimo aplikaci…":"Nie ma tego w aplikacji, szukam odpowiedzi poza aplikacją…","Nenašli jste, co jste hledali?":"Nie znalazłeś tego, czego szukasz?","Zeptat se mimo aplikaci":"Zapytaj poza aplikacją","Pozor: {t}":"Uwaga: {t}","DIGI parťák říká: ":"DIGI parťák mówi: ","Vy: ":"Ty: ","Dobrý den! Jsem DIGI parťák.":"Dzień dobry! Jestem DIGI parťák.","Zeptejte se vlastními slovy, nebo si vyberte téma. Nejdřív hledám v knihovně ověřených rad. Když tam odpověď není, zkusím poradit jinak – ale vždy vás upozorním, ať si to ověříte.":"Zapytaj własnymi słowami albo wybierz temat. Najpierw szukam w bibliotece sprawdzonych porad. Jeśli tam nie ma odpowiedzi, spróbuję pomóc inaczej – ale zawsze przypomnę, żeby to sprawdzić.","Dobrý den! Jsem DIGI parťák. Zeptejte se vlastními slovy, nebo si vyberte téma.":"Dzień dobry! Jestem DIGI parťák. Zapytaj własnymi słowami albo wybierz temat.","číslo karty":"numer karty","rodné číslo":"numer identyfikacyjny (PESEL / czeskie rodné číslo)","heslo nebo kód":"hasło lub kod"," Pozor na citlivé údaje":" Uwaga na dane wrażliwe","Ve vaší zprávě bylo {what}. Skryl jsem to a nikam se to neodeslalo.":"Twoja wiadomość zawierała: {what}. Ukryłem to i nigdzie tego nie wysłano.","Tyto údaje prosím nikdy nikomu nepište – ani do chatu, ani do SMS či e-mailu.":"Nigdy nikomu nie podawaj tych danych – ani w czacie, ani w SMS-ie czy e-mailu.","Jste bez internetu.":"Jesteś bez internetu.","Bez internetu umím odpovídat jen z knihovny ověřených rad. Vyberte si téma, nebo to zkuste znovu, až budete připojeni.":"Bez internetu mogę odpowiadać tylko z biblioteki sprawdzonych porad. Wybierz temat albo spróbuj ponownie po połączeniu.","V ověřené knihovně to není a odpověď mimo aplikaci se teď nepodařilo získat. Zkuste to za chvíli, napište to jinými slovy, nebo se zeptejte člověka.":"W sprawdzonej bibliotece tego nie ma, a odpowiedzi spoza aplikacji nie udało się teraz uzyskać. Spróbuj za chwilę, napisz to innymi słowami albo zapytaj człowieka.","Zkuste to napsat jinými slovy, vyberte si téma, nebo se zeptejte člověka.":"Spróbuj napisać to innymi słowami, wybierz temat albo zapytaj człowieka.","Možná hledáte:":"Może szukasz:","Senior telefon 800 157 157":"Senior telefon 800 157 157","Promiňte, na tohle nemám ověřenou odpověď. Nechci vám radit nepřesně.":"Przepraszam, nie mam na to sprawdzonej odpowiedzi. Nie chcę doradzić nieprecyzyjnie.","Informace mimo aplikaci – ověřte si ji":"Informacja spoza aplikacji – sprawdź ją","Tohle v ověřené knihovně DIGI parťáka není. Odpověď připravila umělá inteligence z obecných znalostí. Může obsahovat chybu nebo být zastaralá.":"Tego nie ma w sprawdzonej bibliotece DIGI parťáka. Odpowiedź przygotowała sztuczna inteligencja na podstawie wiedzy ogólnej. Może zawierać błąd lub być nieaktualna.","Jak si to ověřit:":"Jak to sprawdzić:","Zeptejte se blízkého člověka, kterému věříte.":"Zapytaj bliską osobę, której ufasz.","Podívejte se na oficiální web instituce – adresu napište sami.":"Zajrzyj na oficjalną stronę instytucji – adres wpisz samodzielnie.","Zavolejte bezplatně na Senior telefon 800 157 157.":"Zadzwoń bezpłatnie do Senior telefon 800 157 157 (czeska infolinia).","Než cokoli zaplatíte nebo nainstalujete, nejdřív si informaci ověřte.":"Zanim cokolwiek zapłacisz lub zainstalujesz, najpierw sprawdź informację."," Důležité – jednejte hned":" Ważne – działaj od razu","Ověřená rada":"Sprawdzona porada","Odkud to víme":"Skąd to wiemy","Mohlo by vás zajímat:":"Może Cię zainteresować:","Sem vložte nebo opište text podezřelé zprávy…":"Wklej lub przepisz tutaj tekst podejrzanej wiadomości…","Nejdřív prosím vložte text zprávy.":"Najpierw wklej tekst wiadomości.","Text jsem vložil.":"Wkleiłem tekst.","Schránka je prázdná.":"Schowek jest pusty.","Vložte text podržením prstu v poli a volbou „Vložit“.":"Wklej tekst, przytrzymując palec w polu i wybierając „Wklej”.","Vložit zkopírovaný text":"Wklej skopiowany tekst","Vložte text podezřelé zprávy, nebo nahrajte její fotku či snímek obrazovky. Ukážu vám varovné znaky a poradím, co bezpečně udělat.":"Wklej tekst podejrzanej wiadomości albo prześlij jej zdjęcie lub zrzut ekranu. Pokażę sygnały ostrzegawcze i doradzę, co bezpiecznie zrobić.","Zkontrolovat fotku zprávy":"Sprawdź zdjęcie wiadomości","Udělejte snímek obrazovky podezřelé SMS, e-mailu nebo zprávy a nahrajte ho sem. Můžete zprávu i vyfotit jiným telefonem.":"Zrób zrzut ekranu podejrzanego SMS-a, e-maila lub wiadomości i prześlij go tutaj. Możesz też sfotografować wiadomość innym telefonem.","Nahrát snímek obrazovky":"Prześlij zrzut ekranu","Vyfotit zprávu":"Zrób zdjęcie wiadomości","Fotka se odešle k rozboru umělé inteligenci (Claude od firmy Anthropic). Nikde ji neukládáme. Číslo karty nebo kódy na fotce raději zakryjte.":"Zdjęcie zostanie wysłane do analizy sztucznej inteligencji (Claude firmy Anthropic). Nigdzie go nie zapisujemy. Numer karty lub kody na zdjęciu lepiej zakryj.","Nevíte, jak udělat snímek obrazovky? ":"Nie wiesz, jak zrobić zrzut ekranu? ","Návod pro Android":"Poradnik dla Androida","Návod pro iPhone":"Poradnik dla iPhone'a","Nebo vložte text zprávy":"Albo wklej tekst wiadomości","Text zprávy":"Tekst wiadomości","Kontrola textu probíhá jen ve vašem zařízení. Text nikam neodesíláme.":"Sprawdzanie tekstu odbywa się tylko na Twoim urządzeniu. Nigdzie nie wysyłamy tekstu.","Zkontrolovat text":"Sprawdź tekst","Vymazat":"Wyczyść","Vyzkoušet na ukázkové podvodné SMS":"Wypróbuj na przykładowym fałszywym SMS-ie","Zlaté pravidlo":"Złota zasada","Když zpráva spěchá a chce peníze nebo údaje – ":"Gdy wiadomość ponagla i chce pieniędzy lub danych – ","zastavte se a ověřte si to sami.":"zatrzymaj się i sprawdź to sam.","Zavolejte bance, poště nebo úřadu na číslo z jejich oficiálního webu nebo z platební karty – nikdy na číslo či odkaz ze zprávy.":"Zadzwoń do banku, na pocztę lub do urzędu na numer z ich oficjalnej strony lub z karty płatniczej – nigdy na numer czy link z wiadomości.","Vyberte prosím obrázek.":"Wybierz obraz.","Obrázek je moc velký. Zkuste udělat snímek obrazovky.":"Obraz jest za duży. Spróbuj zrobić zrzut ekranu.","Tento obrázek neumím otevřít. Zkuste snímek obrazovky ve formátu JPG nebo PNG.":"Nie umiem otworzyć tego obrazu. Spróbuj zrzutu ekranu w formacie JPG lub PNG.","Prohlížím fotku… může to trvat až půl minuty.":"Oglądam zdjęcie… może to potrwać do pół minuty.","Náhled nahrané fotky zprávy":"Podgląd przesłanego zdjęcia wiadomości","Jste bez internetu. Rozbor fotky potřebuje internet – zkuste prosím opsat text zprávy do pole níže.":"Jesteś bez internetu. Analiza zdjęcia potrzebuje internetu – przepisz tekst wiadomości do pola poniżej.","Rozbor fotky se teď nepodařil. Zkuste to prosím za chvíli, nebo opište text zprávy do pole níže.":"Analiza zdjęcia się teraz nie udała. Spróbuj za chwilę albo przepisz tekst wiadomości do pola poniżej.","Velmi podezřelé!":"Bardzo podejrzane!","Zpráva má několik typických znaků podvodu. Na nic neklikejte a nic neplaťte.":"Wiadomość ma kilka typowych cech oszustwa. Niczego nie klikaj i niczego nie płać.","Buďte opatrní":"Zachowaj ostrożność","Našel jsem varovné znaky. Než cokoli uděláte, ověřte si zprávu jinou cestou.":"Znalazłem sygnały ostrzegawcze. Zanim cokolwiek zrobisz, sprawdź wiadomość inną drogą.","Nenašel jsem typické znaky podvodu":"Nie znalazłem typowych cech oszustwa","To ale neznamená, že je zpráva určitě v pořádku. Podvodníci vymýšlejí stále nové triky.":"To jednak nie znaczy, że wiadomość jest na pewno w porządku. Oszuści wymyślają ciągle nowe sztuczki.","Fotku se nepodařilo posoudit":"Nie udało się ocenić zdjęcia","Na fotce nevidím čitelnou zprávu. Zkuste ostřejší snímek obrazovky, na kterém je celý text, nebo text opište do pole.":"Na zdjęciu nie widzę czytelnej wiadomości. Spróbuj ostrzejszego zrzutu ekranu z całym tekstem albo przepisz tekst do pola.","Pokud vás zpráva o něco žádá, ověřte si to u odesílatele na známém čísle.":"Jeśli wiadomość o coś prosi, sprawdź to u nadawcy pod znanym numerem.","Nikdy nezadávejte PIN, hesla ani kódy z SMS přes odkaz.":"Nigdy nie podawaj PIN-u, haseł ani kodów z SMS przez link.","Na odkaz ve zprávě neklikejte a neodpovídejte.":"Nie klikaj w link w wiadomości i nie odpowiadaj.","Ověřte si to sami – zavolejte na oficiální číslo instituce nebo blízkému člověku.":"Sprawdź to sam – zadzwoń na oficjalny numer instytucji albo do bliskiej osoby.","Zprávu smažte a odesílatele zablokujte.":"Usuń wiadomość i zablokuj nadawcę.","Pokud jste už něco vyplnili nebo zaplatili, hned volejte svou banku.":"Jeśli już coś wypełniłeś lub zapłaciłeś, od razu zadzwoń do swojego banku.","Rozbor fotky pomocí umělé inteligence. Výsledek je orientační, ověřte si ho. ":"Analiza zdjęcia przez sztuczną inteligencję. Wynik jest orientacyjny, sprawdź go. ","Co udělat: {t}":"Co zrobić: {t}","Rozbor fotky pomocí umělé inteligence":"Analiza zdjęcia przez sztuczną inteligencję","Výsledek je orientační a může obsahovat chybu. Když si nejste jistí, ověřte si to u blízkého nebo na Senior telefonu 800 157 157.":"Wynik jest orientacyjny i może zawierać błąd. Jeśli nie masz pewności, sprawdź to u bliskiej osoby lub w Senior telefon 800 157 157.","Výsledek kontroly":"Wynik sprawdzenia","Čeho jsem si všiml:":"Co zauważyłem:","Co teď bezpečně udělat:":"Co teraz bezpiecznie zrobić:","Text, který jsem na fotce přečetl":"Tekst, który przeczytałem na zdjęciu","Už jsem klikl/a – co teď?":"Już kliknąłem – co teraz?","Návody krok za krokem":"Poradniki krok po kroku","Vyberte si, co se chcete naučit. Na každé obrazovce je jen jeden krok. Můžete se kdykoli vrátit.":"Wybierz, czego chcesz się nauczyć. Na każdym ekranie jest tylko jeden krok. W każdej chwili możesz wrócić.","{n} kroků · asi {m} min":"{n} kroków · ok. {m} min","Všechny návody":"Wszystkie poradniki","Začít":"Zacznij","Zdroj: {t}":"Źródło: {t}","Postup návodem":"Postęp poradnika","Krok {i} z {n}":"Krok {i} z {n}","Tip: ":"Wskazówka: ","Krok {i}":"Krok {i}","Zvládli jste to!":"Udało się!","Výborně. Návod si můžete kdykoli zopakovat.":"Świetnie. Możesz powtórzyć poradnik w każdej chwili.","Zpět":"Wstecz","Další krok":"Następny krok","Hotovo":"Gotowe","Pomoc a důležitá čísla":"Pomoc i ważne numery","Klepnutím na číslo rovnou zavoláte. Ve vážné situaci neváhejte – raději zavolejte.":"Dotknij numeru, aby od razu zadzwonić. W poważnej sytuacji nie wahaj się – lepiej zadzwoń.","Tísňová volání":"Numery alarmowe","Když potřebujete poradit nebo si promluvit":"Gdy potrzebujesz porady lub rozmowy"," Ztratili jste kartu nebo vás někdo okradl?":" Zgubiłeś kartę albo ktoś Cię okradł?","Hned zavolejte do své banky a kartu zablokujte. Číslo najdete na webu banky nebo ve smlouvě.":"Od razu zadzwoń do swojego banku i zablokuj kartę. Numer znajdziesz na stronie banku lub w umowie.","Krádež nebo podvod oznamte Policii ČR na čísle 158.":"Kradzież lub oszustwo zgłoś czeskiej policji pod numerem 158.","Čísla připravena podle oficiálních zdrojů (IZS, Život 90, Elpida). Před zveřejněním aplikace je ověřte.":"Numery przygotowane według oficjalnych źródeł (IZS, Život 90, Elpida). Sprawdź je przed publikacją aplikacji.","zapnuto":"włączone","vypnuto":"wyłączone","Zapnuto":"Włączone","Vypnuto":"Wyłączone","Nastavení":"Ustawienia","Upravte si parťáka tak, aby se vám dobře četl a používal.":"Dostosuj pomocnika tak, aby dobrze się go czytało i używało.","Jazyk":"Język","Velikost písma":"Rozmiar tekstu","Ukázka: Takhle velké bude písmo v celé aplikaci.":"Przykład: tak duży będzie tekst w całej aplikacji.","Vysoký kontrast":"Wysoki kontrast","Výraznější barvy a silnější okraje pro horší zrak.":"Wyraźniejsze kolory i grubsze ramki dla słabszego wzroku.","Číst odpovědi nahlas":"Czytaj odpowiedzi na głos","Parťák vám každou odpověď v chatu sám přečte.":"Pomocnik sam przeczyta każdą odpowiedź w czacie.","Pomalejší čtení":"Wolniejsze czytanie","Hlas bude mluvit pomaleji a zřetelněji.":"Głos będzie mówił wolniej i wyraźniej.","Parťák na ploše telefonu":"DIGI parťák na ekranie głównym"," Aplikace je nainstalovaná. Výborně!":" Aplikacja jest zainstalowana. Świetnie!","Přidejte si DIGI parťáka na plochu. Otevřete ho pak jedním klepnutím, jako každou jinou aplikaci.":"Dodaj DIGI parťáka do ekranu głównego. Otworzysz go jednym dotknięciem, jak każdą inną aplikację.","Hotovo! Parťák je na ploše.":"Gotowe! DIGI parťák jest na ekranie głównym.","Přidat na plochu":"Dodaj do ekranu głównego","Návod krok za krokem":"Poradnik krok po kroku","Soukromí a bezpečí":"Prywatność i bezpieczeństwo","Aplikace nemá žádný účet ani registraci.":"Aplikacja nie ma konta ani rejestracji.","Kontrola vloženého textu v sekci „Je to podvod?“ probíhá jen ve vašem zařízení. Rozhovory se neukládají a po zavření zmizí.":"Sprawdzanie wklejonego tekstu w sekcji „Czy to oszustwo?” odbywa się tylko na Twoim urządzeniu. Rozmowy nie są zapisywane i znikają po zamknięciu.","V zařízení si pamatujeme jen vaše nastavení (velikost písma, kontrast).":"Na urządzeniu zapamiętujemy tylko Twoje ustawienia (rozmiar tekstu, kontrast, język).","Když otázka není v knihovně ověřených rad, odešle se (bez čísel karet, PINů a hesel) k zodpovězení umělé inteligenci Claude od firmy Anthropic. Taková odpověď je vždy označená „Informace mimo aplikaci“. Stejně tak se k rozboru odešle fotka zprávy, kterou nahrajete v sekci „Je to podvod?“. Nic z toho neukládáme.":"Gdy pytania nie ma w bibliotece sprawdzonych porad, zostaje ono wysłane (bez numerów kart, PIN-ów i haseł) do sztucznej inteligencji Claude firmy Anthropic. Taka odpowiedź jest zawsze oznaczona „Informacja spoza aplikacji”. Tak samo do analizy wysyłane jest zdjęcie wiadomości, które prześlesz w sekcji „Czy to oszustwo?”. Niczego z tego nie zapisujemy.","Funkci „Mluvit“ zajišťuje váš prohlížeč (např. Google nebo Apple), který může hlas zpracovat na svém serveru.":"Funkcję „Mów” zapewnia Twoja przeglądarka (np. Google lub Apple), która może przetwarzać głos na swoim serwerze.","Opravdu smazat nastavení a rozhovor? Aplikace se vrátí do výchozího stavu.":"Na pewno usunąć ustawienia i rozmowę? Aplikacja wróci do stanu początkowego.","Vše jsem smazal.":"Wszystko usunąłem.","Smazat vše z tohoto zařízení":"Usuń wszystko z tego urządzenia","O aplikaci":"O aplikacji","DIGI parťák je trpělivý digitální průvodce pro seniory. Chatbot nejdřív hledá v knihovně předem připravených a zkontrolovaných rad s uvedenými zdroji. Teprve když tam odpověď není, odpoví pomocí umělé inteligence – takovou odpověď vždy výrazně označí jako neověřenou.":"DIGI parťák to cierpliwy cyfrowy przewodnik dla seniorów. Chatbot najpierw szuka w bibliotece przygotowanych i sprawdzonych porad ze źródłami. Dopiero gdy tam nie ma odpowiedzi, odpowiada za pomocą sztucznej inteligencji – i zawsze wyraźnie oznacza taką odpowiedź jako niesprawdzoną.","Parťák nenahrazuje lékaře, banku, policii ani právníka. Ve vážné situaci volejte 112.":"DIGI parťák nie zastępuje lekarza, banku, policji ani prawnika. W poważnej sytuacji dzwoń pod 112.","Stav knihovny rad: {s}. Počet ověřených témat: {n}.":"Stan biblioteki porad: {s}. Liczba sprawdzonych tematów: {n}.","Změnit jazyk":"Zmień język","Jazyk se nepodařilo načíst. Zkontrolujte internet.":"Nie udało się wczytać języka. Sprawdź połączenie z internetem.","Jazyk změněn: {name}":"Zmieniono język: {name}","Vyberte jazyk aplikace. Ověřené rady jsou ve všech jazycích stejné.":"Wybierz język aplikacji. Sprawdzone porady są takie same we wszystkich językach.","Rady se týkají života v Česku – telefonní čísla a instituce jsou české.":"Porady dotyczą życia w Czechach – numery telefonów i instytucje są czeskie.","Jste znovu připojeni k internetu.":"Znów jesteś online.","Jste offline. Parťák ale funguje dál.":"Jesteś offline. DIGI parťák nadal działa.","Běžné":"Zwykły","Velké":"Duży","Největší":"Największy","Domů":"Start","Vase zasilka nemohla byt dorucena. Pro opetovne doruceni uhradte poplatek 32 Kc ihned na www.posta-doruceni-cz.top":"Twoja przesylka nie mogla zostac dostarczona. Aby ja ponownie dostarczyc, zaplac natychmiast oplate 32 CZK na www.poczta-dostawa-cz.top","Pozor, jde o informaci mimo aplikaci. Není z ověřené knihovny DIGI parťáka, připravila ji umělá inteligence a může obsahovat chybu. Informaci si prosím ověřte.":"Uwaga, to informacja spoza aplikacji. Nie pochodzi ze sprawdzonej biblioteki DIGI parťáka, przygotowała ją sztuczna inteligencja i może zawierać błąd. Sprawdź tę informację.","Přeskočit na obsah":"Przejdź do treści","DIGI parťák – domů":"DIGI parťák – start","Hlavní navigace":"Nawigacja główna","Návody":"Poradniki","Změnit velikost písma":"Zmień rozmiar tekstu","Písmo":"Tekst","Pomoc":"Pomoc","Spodní navigace":"Nawigacja dolna","Podvod?":"Oszustwo?","Obsahuje odkaz":"Zawiera link","Podvodníci posílají odkazy na falešné stránky, kde chtějí údaje z karty nebo hesla.":"Oszuści wysyłają linki do fałszywych stron, na których chcą danych karty lub haseł.","Zkrácený odkaz":"Skrócony link","Zkrácený odkaz skrývá, kam vás ve skutečnosti zavede.":"Skrócony link ukrywa, dokąd naprawdę prowadzi.","Chce údaje z karty, heslo nebo kód":"Chce danych karty, hasła lub kodu","Banka, pošta ani úřad po vás tyto údaje ve zprávě nikdy nechtějí.":"Bank, poczta ani urząd nigdy nie proszą o te dane w wiadomości.","Tlačí vás do spěchu":"Ponagla Cię","Spěch a strach jsou hlavní zbraně podvodníků. Skutečné instituce vám dají čas.":"Pośpiech i strach to główna broń oszustów. Prawdziwe instytucje dają czas.","Chce, abyste něco zaplatili":"Chce, żebyś coś zapłacił","Podvodníci často chtějí „poplatek“, doplatek nebo úhradu. Je to záminka, jak získat vaše peníze nebo údaje z karty.":"Oszuści często chcą „opłaty”, dopłaty lub płatności. To pretekst, by zdobyć Twoje pieniądze lub dane karty.","Tváří se jako doručení balíku":"Udaje dostawę paczki","Falešné zprávy o balících jsou jedním z nejčastějších podvodů.":"Fałszywe wiadomości o paczkach to jedno z najczęstszych oszustw.","Vydává se za banku, úřad nebo firmu":"Podszywa się pod bank, urząd lub firmę","Podvodníci se rádi vydávají za důvěryhodné instituce. Ověřte si to sami na oficiálním čísle.":"Oszuści chętnie podszywają się pod zaufane instytucje. Sprawdź to sam pod oficjalnym numerem.","Žádá převod peněz":"Żąda przelewu pieniędzy","Žádný skutečný bankéř ani policista vás nežádá o převod na „bezpečný účet“.":"Żaden prawdziwy bankowiec ani policjant nie poprosi o przelew na „bezpieczne konto”.","Slibuje výhru nebo dárek":"Obiecuje wygraną lub prezent","Pokud jste se soutěže neúčastnili, nemůžete nic vyhrát.":"Jeśli nie brałeś udziału w konkursie, nie mogłeś nic wygrać.","Vydává se za někoho z rodiny":"Podszywa się pod członka rodziny","Častý trik „Ahoj mami, mám nové číslo“. Zavolejte blízkému na jeho staré číslo.":"Częsty trik „Cześć mamo, mam nowy numer”. Zadzwoń do bliskiej osoby na jej stary numer.","Žádá o peníze":"Prosi o pieniądze","Kdykoli vás zpráva žádá o peníze, ověřte si odesílatele jinou cestou – nejlépe telefonátem na známé číslo.":"Gdy wiadomość prosi o pieniądze, sprawdź nadawcę inną drogą – najlepiej dzwoniąc na znany numer.","Chce, abyste si něco nainstalovali":"Chce, żebyś coś zainstalował","Aplikace pro vzdálený přístup dávají podvodníkovi kontrolu nad vaším zařízením.":"Aplikacje do zdalnego dostępu dają oszustowi kontrolę nad Twoim urządzeniem.","Slibuje rychlý zisk":"Obiecuje szybki zysk","Zaručené a vysoké výnosy neexistují. Je to typický investiční podvod.":"Gwarantowane wysokie zyski nie istnieją. To typowe oszustwo inwestycyjne.","Zahraniční telefonní číslo":"Zagraniczny numer telefonu","Zpráva přišla nebo odkazuje na číslo mimo Česko (předvolba jiná než +420).":"Wiadomość przyszła z numeru spoza Czech lub do niego odsyła (prefiks inny niż +420).","Česká pošta":"Poczta Czeska (Česká pošta)","Policie ČR":"Policja Czeska (Policie ČR)","Česká bankovní asociace":"Czeskie Stowarzyszenie Bankowe","NÚKIB – Národní úřad pro kybernetickou a informační bezpečnost":"NÚKIB – czeski Narodowy Urząd ds. Cyberbezpieczeństwa","Česká národní banka":"Czeski Bank Narodowy","Česká obchodní inspekce":"Czeska Inspekcja Handlowa","Nápověda Android (Google)":"Pomoc Android (Google)","Podpora Apple":"Wsparcie Apple","Nápověda WhatsApp":"Pomoc WhatsApp","Nápověda Facebooku":"Pomoc Facebooka","Nápověda Seznam.cz":"Pomoc Seznam.cz","Nápověda YouTube":"Pomoc YouTube","Manipulátoři.cz":"Manipulátoři.cz (czeski fact-checking)","Demagog.cz":"Demagog.cz (czeski fact-checking)","Úřad pro ochranu osobních údajů":"Czeski Urząd Ochrony Danych Osobowych","IDOS – jízdní řády":"IDOS – czeskie rozkłady jazdy","Mapy.com":"Mapy.com","SÚKL – eRecept":"SÚKL – eRecept (e-recepta)","Portál občana":"Portal Obywatela (Portál občana)","Integrovaný záchranný systém – tísňová čísla":"Zintegrowany System Ratowniczy – numery alarmowe","Život 90 – Senior telefon":"Život 90 – Senior telefon","Elpida – Linka seniorů":"Elpida – Linia dla seniorów","Nápověda Android (Google), Podpora Apple":"Pomoc Android (Google), Wsparcie Apple","Policie ČR, NÚKIB":"Policja Czeska, NÚKIB","Česká bankovní asociace, Policie ČR":"Czeskie Stowarzyszenie Bankowe, Policja Czeska","SÚKL":"SÚKL","Koncept 11/2026 – před spuštěním nechat zkontrolovat odborníkem":"Wersja robocza 11/2026 – przed uruchomieniem do sprawdzenia przez eksperta"},"kb":{"sms-balik":["Dostałem SMS-a o paczce i mam dopłacić opłatę","Takie wiadomości bardzo często są oszustwem. Oszuści chcą, żebyś przez link podał dane karty płatniczej.",["Nie klikaj w link w wiadomości i niczego nie płać.","Jeśli naprawdę czekasz na paczkę, sprawdź to sam – na oficjalnej stronie przewoźnika lub telefonicznie pod numerem z jego strony.","Usuń wiadomość. Możesz ją też zgłosić jako spam.","Jeśli już kliknąłeś w link i podałeś kartę, od razu zadzwoń do swojego banku."],"Firmy kurierskie nie poproszą o dane karty przez link w SMS-ie."],"banka-vola":["Dzwoni ktoś z banku i chce, żebym przelał pieniądze","Rozłącz się. Bank nigdy nie poprosi o przelew na „bezpieczne konto” ani o PIN, hasło czy kod z SMS.",["Od razu zakończ rozmowę. Nie musisz być uprzejmy.","Niczego nie instaluj i nikomu nie podawaj żadnych kodów.","Sam zadzwoń do swojego banku – na numer z tyłu karty płatniczej lub z oficjalnej strony banku.","Jeśli już wysłałeś pieniądze lub podałeś dane, od razu powiedz o tym bankowi i zadzwoń na czeską policję pod numer 158."],"Oszuści potrafią podszyć się nawet pod prawdziwy numer banku lub policji. Na ekranie może być „właściwy” numer – a mimo to może to być oszustwo."],"uz-jsem-zadal":["Już kliknąłem w link albo podałem dane karty","Spokojnie, wciąż można działać. Im szybciej zadzwonisz do banku, tym większa szansa na uratowanie pieniędzy.",["Od razu zadzwoń do swojego banku na numer z tyłu karty lub z oficjalnej strony banku. Poproś o zablokowanie karty.","Jeśli dałeś komuś dostęp do telefonu lub komputera, wyłącz internet (Wi-Fi i dane).","Zmień hasło do bankowości internetowej i e-maila – najlepiej z pomocą bliskiej osoby.","Zgłoś oszustwo czeskiej policji pod numerem 158.","Nie wstydź się. Oszuści to zawodowcy i nabierają też młodych i doświadczonych ludzi."],""],"falesny-policista":["Dzwoni „policjant” i chce, żebym dał mu pieniądze","Prawdziwa policja nigdy nie poprosi o pieniądze, gotówkę ani przelew. To oszustwo.",["Rozłącz się i nikomu niczego nie przekazuj.","Sam zadzwoń pod 158 i powiedz, co się stało.","Jeśli ktoś stoi pod drzwiami, nie otwieraj i dzwoń pod 158."],""],"vnoucatko":["Pisze do mnie „wnuczek” albo „córka” z nowego numeru i chce pieniędzy","To częste oszustwo. Zanim cokolwiek wyślesz, sprawdź, czy naprawdę pisze do Ciebie bliska osoba.",["Nie wysyłaj pieniędzy ani kodów.","Zadzwoń do bliskiej osoby na jej STARY, znany numer albo zapytaj innego członka rodziny.","Możesz zadać pytanie, na które odpowiedź zna tylko ona (np. imię Twojego psa).","Jeśli okaże się, że to był oszust, zablokuj numer."],""],"vzdalena-plocha":["Ktoś chce, żebym zainstalował aplikację (AnyDesk, TeamViewer)","Nigdy nie instaluj aplikacji na polecenie osoby, która sama do Ciebie zadzwoniła lub napisała. Dałbyś jej dostęp do telefonu i bankowości.",["Zakończ rozmowę lub czat.","Niczego nie instaluj. Jeśli już zainstalowałeś, wyłącz internet i odinstaluj aplikację.","Zadzwoń do banku na oficjalny numer i powiedz, co się stało."],"Banki, Microsoft ani operatorzy nie dzwonią sami w sprawie „wirusów w komputerze”."],"investice":["Ktoś proponuje mi inwestycję, kryptowaluty albo szybki zysk","Obietnica wysokiego, „gwarantowanego” zysku to typowy znak oszustwa. Często wykorzystuje się przy tym zdjęcia znanych osób.",["Nikomu nie wysyłaj pieniędzy ani dokumentów.","Nie instaluj żadnych aplikacji polecanych przez „doradcę”.","Na stronie Czeskiego Banku Narodowego możesz sprawdzić, czy firma ma zezwolenie.","O inwestycjach porozmawiaj osobiście w swoim banku albo z kimś bliskim."],"DIGI parťák nie udziela porad inwestycyjnych – pomaga tylko rozpoznać oszustwo."],"vyhra":["Podobno coś wygrałem i mam zapłacić opłatę","Jeśli nie brałeś udziału w konkursie, nic nie wygrałeś. Prawdziwa wygrana nigdy nie wymaga opłaty ani danych karty.",["Nie klikaj w link i niczego nie płać.","Usuń wiadomość.","Jeśli podałeś kartę, zadzwoń do banku."],""],"jak-poznat-podvod":["Jak rozpoznać fałszywą wiadomość lub e-mail?","Fałszywe wiadomości zwykle mają kilka wspólnych cech. Wystarczy zauważyć jedną z nich i zachować czujność.",["Pośpiech i strach: „natychmiast”, „w ciągu 24 godzin”, „konto zostanie zablokowane”.","Link, pod którym masz coś wypełnić lub zapłacić.","Prośba o numer karty, PIN, hasło lub kod z SMS.","Nieznany nadawca, zagraniczny numer lub dziwny adres.","Jeśli nie masz pewności, wklej wiadomość do narzędzia „Czy to oszustwo?” albo zapytaj bliską osobę."],""],"heslo":["Jak utworzyć bezpieczne hasło?","Najlepsze jest długie hasło z kilku słów, które łatwo zapamiętasz, a nikt inny go nie zgadnie.",["Połącz 3–4 niepowiązane słowa, np. „Kos-Bulka-Ogrod-27” (ale tego nie używaj, jest publiczne).","Do każdego konta używaj innego hasła – zwłaszcza do e-maila i banku.","Hasła możesz zapisać w zeszycie, który zostaje w domu. Nigdy ich nie fotografuj ani nie wysyłaj.","Gdzie się da, włącz weryfikację dwuetapową (kod SMS lub w aplikacji)."],"Nigdy nikomu nie podawaj hasła – ani bankowi, ani „technikowi”. Ani DIGI parťákowi."],"nakup-online":["Jak bezpiecznie robić zakupy w internecie?","Kupuj w znanych sklepach internetowych, a przy nieznanych najpierw sprawdź, kto za nimi stoi.",["Adres sklepu wpisz sam, nie klikaj w linki z reklam i wiadomości.","Sprawdź kontakt, numer firmy i adres sprzedawcy oraz opinie innych ludzi.","Uważaj, gdy cena jest podejrzanie niska.","U nieznanego sprzedawcy wybierz płatność przy odbiorze.","Na serwisach ogłoszeniowych nigdy nie wysyłaj kodu z SMS ani nie podawaj karty przez link od „kupującego”."],""],"laska-online":["Poznałem kogoś w internecie i ta osoba chce pieniędzy","Jeśli o pieniądze prosi ktoś, kogo nigdy nie spotkałeś osobiście, to z dużym prawdopodobieństwem oszustwo.",["Nie wysyłaj pieniędzy, prezentów ani kodów.","Porozmawiaj o tym z kimś bliskim.","Jeśli już wysłałeś pieniądze, zadzwoń do banku i na czeską policję (158)."],""],"pismo":["Jak powiększyć tekst w telefonie?","Tekst powiększysz w Ustawieniach telefonu. Nazwy pozycji mogą się trochę różnić w zależności od producenta.",["Android: otwórz Ustawienia → Wyświetlacz (lub Ułatwienia dostępu) → Rozmiar czcionki.","iPhone: otwórz Ustawienia → Ekran i jasność → Wielkość tekstu.","Przesuń suwak w prawo, aż tekst będzie dobrze czytelny.","W DIGI parťáku tekst powiększysz przyciskiem „Tekst” u góry."],""],"whatsapp-fotka":["Jak wysłać zdjęcie przez WhatsApp?","Zdjęcie wyślesz w kilku krokach prosto z rozmowy z daną osobą.",["Otwórz WhatsApp i dotknij imienia osoby.","Na dole dotknij ikony spinacza lub „+”.","Wybierz „Galeria” (Android) lub „Zdjęcia” (iPhone).","Dotknij zdjęcia, a potem zielonej strzałki, aby je wysłać."],""],"whatsapp-video":["Jak zadzwonić z wideo przez WhatsApp?","Rozmowę wideo rozpoczniesz jednym dotknięciem w czacie z daną osobą.",["Otwórz WhatsApp i dotknij imienia osoby.","W prawym górnym rogu dotknij ikony kamery.","Poczekaj, aż druga osoba odbierze.","Rozmowę zakończysz czerwonym przyciskiem."],""],"wifi":["Jak połączyć się z Wi-Fi?","Z domowym Wi-Fi połączysz się w Ustawieniach. Potrzebujesz nazwy sieci i hasła – zwykle są na naklejce na routerze.",["Otwórz Ustawienia → Wi-Fi (na Androidzie czasem Połączenia → Wi-Fi).","Włącz Wi-Fi, jeśli jest wyłączone.","Dotknij nazwy swojej sieci.","Wpisz hasło z naklejki na routerze i potwierdź."],"W publicznym Wi-Fi (kawiarnia, dworzec) lepiej nie korzystaj z bankowości internetowej."],"aktualizace":["Czy mam aktualizować telefon?","Tak, aktualizacje z Ustawień telefonu są ważne – naprawiają błędy bezpieczeństwa.",["Uruchamiaj aktualizacje tylko z Ustawień telefonu lub ze sklepu Google Play / App Store.","Przed aktualizacją naładuj telefon i połącz go z Wi-Fi.","Jeśli do „aktualizacji” wzywa link w SMS-ie lub e-mailu, to oszustwo."],""],"screenshot":["Jak zrobić zrzut ekranu?","Zrzut ekranu to „zdjęcie” tego, co masz właśnie na ekranie. Przydaje się np. do sprawdzenia podejrzanego SMS-a w DIGI parťáku.",["Android: naciśnij jednocześnie przycisk zasilania i przycisk ściszania (dolny) i od razu puść.","iPhone bez przycisku Początek: naciśnij jednocześnie przycisk boczny i przycisk zwiększania głośności (górny).","iPhone z przyciskiem Początek (okrągły na dole): naciśnij jednocześnie przycisk Początek i przycisk boczny (lub górny).","Ekran krótko mignie. Zrzut znajdziesz w Galerii (Android) lub w Zdjęciach (iPhone)."],"W niektórych telefonach z Androidem kombinacja przycisków różni się w zależności od producenta."],"plocha":["Jak dodać DIGI parťáka do ekranu głównego telefonu?","Możesz dodać DIGI parťáka do ekranu głównego jak zwykłą aplikację. Potem otworzysz go jednym dotknięciem.",["Android (Chrome): dotknij trzech kropek w prawym górnym rogu → „Dodaj do ekranu głównego” lub „Zainstaluj aplikację”.","iPhone (Safari): dotknij ikony Udostępnij na dole (kwadrat ze strzałką) → „Do ekranu początkowego”.","Potwierdź przyciskiem „Dodaj”."],""],"facebook":["Co to jest Facebook i jak zacząć z niego korzystać?","Facebook to sieć społecznościowa – miejsce w internecie, gdzie ludzie dzielą się zdjęciami i nowinkami oraz wysyłają sobie wiadomości (przez aplikację Messenger). Korzystanie jest bezpłatne.",["Pobierz aplikację Facebook ze sklepu Google Play (Android) lub App Store (iPhone) albo sam wpisz w przeglądarce facebook.com.","Nowe konto: dotknij „Utwórz nowe konto” i podaj imię, datę urodzenia oraz e-mail lub telefon. Wybierz hasło.","Logowanie: wpisz e-mail lub telefon i hasło, a potem dotknij „Zaloguj się”.","W ustawieniach prywatności wybierz, że Twoje posty widzą tylko „Znajomi”.","Przyjmuj zaproszenia do znajomych tylko od osób, które naprawdę znasz."],"Na Facebooku są fałszywe profile i reklamy „gwarantowanych zarobków” ze znanymi osobami. Gdy ktoś prosi o pieniądze, sprawdź to telefonicznie."],"whatsapp-zacit":["Co to jest WhatsApp i jak go zainstalować?","WhatsApp to aplikacja do wiadomości, zdjęć i rozmów (także wideo) przez internet. Przez Wi-Fi jest bezpłatna, także za granicę. Korzysta z Twojego numeru telefonu.",["Otwórz Sklep Google Play (Android) lub App Store (iPhone) i wyszukaj „WhatsApp Messenger”.","Sprawdź, czy wydawcą jest „WhatsApp LLC”, i dotknij Zainstaluj (Pobierz).","Otwórz WhatsApp, zaakceptuj warunki i wpisz swój numer telefonu.","Dostaniesz SMS z kodem – wpisz go tylko bezpośrednio w WhatsAppie.","Wpisz swoje imię. Twoje kontakty, które mają WhatsApp, pojawią się same."],"Nigdy nikomu nie wysyłaj kodu weryfikacyjnego z WhatsAppa – nawet „znajomemu”, który o niego prosi. Tak oszuści kradną konta."],"email":["Jak założyć e-mail i wysłać wiadomość z załącznikiem?","E-mail to poczta elektroniczna. W Czechach najpopularniejsze są e-mail na Seznam.cz i Gmail od Google. Oba są bezpłatne.",["Zakładanie: na stronie seznam.cz dotknij „E-mail” i „Zaregistrovat se”, albo załóż konto Google (Gmail) – na Androidzie zwykle już je masz.","Wymyśl adres (np. jana.novakova@seznam.cz) i bezpieczne hasło. Zapisz jedno i drugie.","Wysyłanie: dotknij „Napisz”, w polu „Do” wpisz adres, napisz temat i tekst.","Załącznik (zdjęcie): dotknij ikony spinacza i wybierz zdjęcie.","Dotknij „Wyślij” (strzałka)."],"E-maile, które chcą hasła, płatności lub kliknięcia w link, często są oszustwem. Jeśli nie masz pewności, wklej je do „Czy to oszustwo?”."],"youtube":["Co to jest YouTube i jak szukać na nim filmów?","YouTube to strona i aplikacja z filmami – piosenki, programy, przepisy, poradniki. Jest bezpłatny, tylko czasem odtwarza się reklama.",["Otwórz aplikację YouTube (zwykle jest już w telefonie) albo wpisz w przeglądarce youtube.com.","Dotknij lupy u góry i napisz, czego szukasz (np. „Anna German” albo „pierogi przepis”).","Dotknij filmu. Reklamę możesz po kilku sekundach pominąć przyciskiem „Pomiń”.","Film powiększysz na cały ekran, obracając telefon poziomo."],"Reklamy szybkiego wzbogacenia się lub cudownych leków to często oszustwo, nawet jeśli występują w nich znane osoby."],"aplikace-instalace":["Jak bezpiecznie zainstalować aplikację?","Aplikacje pobieraj tylko z oficjalnego sklepu: Google Play na Androidzie, App Store na iPhonie. Większość aplikacji jest bezpłatna.",["Otwórz Sklep Google Play (kolorowy trójkąt) lub App Store (niebieskie „A”).","U góry dotknij wyszukiwania i wpisz nazwę aplikacji.","Sprawdź nazwę wydawcy (np. przy aplikacji bankowej Twój bank) i oceny.","Dotknij „Zainstaluj” (Android) lub „Pobierz” (iPhone) i poczekaj.","Odinstalowanie: przytrzymaj palec na ikonie aplikacji i wybierz „Odinstaluj” / „Usuń aplikację”."],"Nigdy nie instaluj aplikacji na polecenie nieznanego rozmówcy ani z linku w SMS-ie."],"zapomenute-heslo":["Zapomniałem hasła – co teraz?","Zapomniane hasło prawie zawsze można odzyskać. Serwis wyśle kod na telefon lub e-mail, a Ty ustawisz nowe hasło.",["Na stronie logowania dotknij „Nie pamiętasz hasła?”.","Wpisz swój e-mail lub telefon. Dostaniesz SMS lub e-mail z kodem albo linkiem.","Kod wpisz tylko na tej stronie, na której sam zacząłeś odzyskiwanie.","Wymyśl nowe hasło i zapisz je w zeszycie, który zostaje w domu.","W przypadku bankowości internetowej zadzwoń do banku na numer z tyłu karty."],"Jeśli dostaniesz kod do zmiany hasła, o który nie prosiłeś, nikomu go nie wysyłaj – ktoś może próbować dostać się do Twojego konta."],"baterie":["Telefon szybko się rozładowuje – co z tym zrobić?","Najwięcej energii zużywają jasny ekran, nawigacja, filmy i aplikacje działające w tle. Kilka zmian wyraźnie wydłuży czas pracy.",["Zmniejsz jasność ekranu (pociągnij pasek z góry i przesuń suwak ze słoneczkiem).","Włącz tryb oszczędzania: Android – Ustawienia → Bateria → Oszczędzanie energii; iPhone – Ustawienia → Bateria → Tryb niskiego zużycia energii.","Zamknij aplikacje, których nie używasz, i wyłącz lokalizację (GPS), gdy jej nie potrzebujesz.","Ładuj oryginalną lub dobrą ładowarką. Nie musisz czekać, aż telefon całkiem się rozładuje.","Jeśli telefon ma kilka lat i mimo to szybko się rozładowuje, może pomóc wymiana baterii w serwisie."],""],"pamet":["Telefon zgłasza pełną pamięć – jak zwolnić miejsce?","Miejsce w telefonie najczęściej zajmują filmy, zdjęcia i pliki z WhatsAppa. Zanim je usuniesz, zrób kopię zapasową.",["Sprawdź, co zajmuje miejsce: Android – Ustawienia → Pamięć (lub Obsługa urządzenia); iPhone – Ustawienia → Ogólne → iPhone: Pamięć.","Zrób kopię zdjęć (Zdjęcia Google lub iCloud), a potem usuń duże filmy.","W WhatsAppie: Ustawienia → Pamięć i dane → Zarządzaj pamięcią – usuń duże pliki i przekazane filmy.","Odinstaluj aplikacje, których nie używasz.","Na koniec opróżnij kosz w Zdjęciach („Ostatnio usunięte”)."],""],"pomaly-telefon":["Telefon jest wolny albo się zawiesza","Najczęściej pomaga zwykłe ponowne uruchomienie. Telefon „posprząta” wtedy pamięć.",["Uruchom telefon ponownie: przytrzymaj przycisk zasilania i wybierz „Uruchom ponownie” (na iPhonie wyłącz i włącz).","Jeśli telefon w ogóle nie reaguje, przytrzymaj przycisk zasilania dłużej (ok. 10–15 sekund).","Zainstaluj aktualizacje systemu i aplikacji.","Zwolnij miejsce w pamięci – pełna pamięć spowalnia telefon.","Jeśli nic nie pomaga, zapytaj w salonie lub serwisie swojego operatora."],""],"hlasitost":["Nie słyszę dzwonka – jak zrobić telefon głośniej?","Głośność dzwonka ustawisz przyciskami z boku telefonu lub w Ustawieniach. Sprawdź też, czy telefon nie jest w trybie cichym.",["Naciśnij górny przycisk głośności z boku telefonu, gdy nie odtwarza się żaden film.","Android: Ustawienia → Dźwięki i wibracje → Głośność → przesuń „Dzwonek” w prawo.","iPhone: Ustawienia → Dźwięki i haptyka → przesuń suwak „Dzwonek i alerty”. Z boku sprawdź przełącznik trybu cichego (pomarańczowy = cisza).","Wyłącz tryb „Nie przeszkadzać” (ikona księżyca na górnym pasku).","Włącz też wibracje, aby poczuć dzwonek w kieszeni."],""],"blokovani":["Jak zablokować uciążliwy numer?","Numer, który Cię nęka, możesz zablokować w telefonie. Wtedy nikt z niego nie zadzwoni ani nie napisze.",["Android: otwórz aplikację Telefon → Ostatnie, przytrzymaj palec na numerze i wybierz „Zablokuj” (ew. „Zgłoś spam”).","iPhone: otwórz Telefon → Ostatnie, dotknij „i” obok numeru, a potem „Zablokuj tego rozmówcę”.","Przy SMS-ach: otwórz wiadomość, dotknij numeru u góry i wybierz Zablokuj.","Nie musisz odbierać nieznanych numerów. Kto Cię potrzebuje, zostawi wiadomość lub napisze."],"Jeśli dzwoniący twierdzi, że jest z banku lub policji, rozłącz się i sam zadzwoń na oficjalny numer."],"kontakt":["Jak zapisać numer telefonu w kontaktach?","Numer zapiszesz łatwo z aplikacji Telefon lub Kontakty. Wtedy przy połączeniu zobaczysz imię zamiast numeru.",["Otwórz aplikację Telefon → Ostatnie i dotknij numeru, który chcesz zapisać.","Wybierz „Utwórz nowy kontakt” lub „Dodaj kontakt” (na iPhonie „i” → Utwórz nowy kontakt).","Wpisz imię i nazwisko, ewentualnie dodaj zdjęcie.","Dotknij „Zapisz” (Gotowe).","Nowy numer możesz dodać też w aplikacji Kontakty przyciskiem „+”."],""],"nouzove-info":["Jak ustawić w telefonie dane medyczne i kontakt alarmowy?","Możesz zapisać w telefonie dane medyczne i kontakt alarmowy. Ratownicy zobaczą je nawet na zablokowanym telefonie.",["iPhone: otwórz aplikację Zdrowie → Twoje zdjęcie w prawym górnym rogu → Karta medyczna → Edytuj. Uzupełnij dane i włącz „Pokazuj po zablokowaniu”.","Android: Ustawienia → Bezpieczeństwo i sytuacje alarmowe (lub Informacje alarmowe). Dokładna nazwa zależy od producenta.","Dodaj kontakt alarmowy – kogoś bliskiego.","Wpisz ważne choroby, alergie i leki, które przyjmujesz."],""],"ztraceny-telefon":["Zgubiłem telefon – jak go znaleźć?","Telefon możesz znaleźć, zablokować lub zdalnie uruchomić dzwonek z komputera albo z telefonu bliskiej osoby.",["Android: na innym urządzeniu otwórz stronę android.com/find i zaloguj się kontem Google.","iPhone: otwórz stronę icloud.com/find i zaloguj się swoim Apple ID (albo użyj aplikacji Znajdź na innym urządzeniu Apple).","Możesz włączyć dzwonek, pokazać telefon na mapie lub go zablokować.","W razie kradzieży zadzwoń do operatora (blokada SIM), do banku (jeśli masz w telefonie bankowość) i na czeską policję pod 158."],""],"zaloha-fotek":["Jak zrobić kopię zdjęć, żeby ich nie stracić?","Zdjęcia z kopią zapasową zapisują się automatycznie także poza telefonem. Gdy zgubisz lub zepsujesz telefon, zdjęcia zostaną.",["Android: otwórz aplikację Zdjęcia Google → Twoja ikona w prawym górnym rogu → włącz „Kopia zapasowa”.","iPhone: Ustawienia → Twoje imię u góry → iCloud → Zdjęcia → włącz „Synchronizuj ten iPhone”.","Kopia działa najlepiej przez Wi-Fi i podczas ładowania.","Za darmo jest tylko ograniczone miejsce. Gdy się skończy, serwis zaproponuje płatne rozszerzenie – nie musisz go kupować, możesz usunąć niepotrzebne."],""],"mobilni-data":["Co to są dane komórkowe i kiedy je włączyć?","Dane komórkowe to internet od Twojego operatora. Działają też na zewnątrz, gdzie nie ma Wi-Fi. Ile masz danych, zależy od taryfy.",["Włączanie: pociągnij palcem pasek od górnej krawędzi i dotknij ikony „Dane komórkowe” (dwie strzałki).","W domu i u bliskich lepiej używaj Wi-Fi – nie zużywa Twoich danych.","Za granicą poza UE wyłącz dane lub roaming, żeby nie dostać wysokiego rachunku. W UE płacisz jak w kraju.","Ile danych Ci zostało, sprawdzisz w aplikacji swojego operatora."],""],"qr-kod":["Jak zeskanować kod QR?","Kod QR to kwadrat z kropek, który zawiera link lub dane płatności. Odczytasz go aparatem telefonu.",["Otwórz Aparat i skieruj go na kod QR (nie rób zdjęcia).","Pojawi się link – dotknij go.","Płatność QR (np. na rachunku): otwórz aplikację swojego banku i wybierz „Płatność kodem QR”. Dane wypełnią się same – sprawdź kwotę i odbiorcę."],"Kody QR w e-mailach, SMS-ach lub naklejone na parkometrach mogą prowadzić na fałszywe strony. Płać tylko w aplikacji swojego banku."],"pin-karty":["Jak zmienić PIN do karty?","PIN do karty zmienisz w aplikacji swojego banku, w bankowości internetowej, w oddziale lub w niektórych bankomatach Twojego banku.",["Otwórz aplikację banku i szukaj przy karcie „Zmień PIN” lub „Pokaż PIN”.","Bez aplikacji idź do oddziału banku z dowodem osobistym.","Nowy PIN wybierz tak, by nie był datą urodzenia ani 1234.","Nie zapisuj PIN-u przy karcie ani w telefonie."],"Bank nigdy nie prosi o PIN – ani telefonicznie, ani SMS-em, ani e-mailem. Kto o niego prosi, jest oszustem."],"internetove-bankovnictvi":["Jak bezpiecznie zacząć z bankowością internetową?","Bankowość internetową założy Ci Twój bank – najpewniej osobiście w oddziale, gdzie od razu pomogą w konfiguracji.",["Idź do oddziału i poproś o bankowość internetową i mobilną. Powiedz, że dopiero zaczynasz.","Aplikację banku pobierz tylko z Google Play lub App Store (wydawcą musi być Twój bank).","Loguj się do banku tylko przez tę aplikację lub adres wpisany samodzielnie. Nigdy przez link z wiadomości.","Rachunek opłać przez „Płatność kodem QR” lub „Nowy przelew”. Przed potwierdzeniem sprawdź numer konta i kwotę."],"Nikomu nie podawaj danych logowania ani kodów potwierdzających. Bank nigdy nie poprosi o przelew na „bezpieczne konto”."],"platba-telefonem":["Jak płacić telefonem zamiast kartą?","Możesz dodać kartę płatniczą do telefonu i płacić, przykładając telefon do terminala, tak samo jak kartą.",["Otwórz aplikację banku i szukaj przy karcie „Dodaj do Google Wallet” lub „Dodaj do Apple Wallet”.","Potwierdź dodanie według instrukcji banku.","Przy płaceniu odblokuj telefon i przyłóż go do terminala.","Zabezpiecz telefon kodem lub odciskiem palca."],""],"hoax":["Jak rozpoznać fałszywą informację (hoax)?","Hoax to alarmująca lub zmyślona wiadomość, która rozprzestrzenia się przez przesyłanie dalej. Często straszy, złości lub obiecuje cuda.",["Zachowaj czujność, gdy wiadomość wzywa „prześlij dalej wszystkim” albo bardzo straszy i oburza.","Szukaj źródła: kto to napisał i gdzie to opublikowano? Rzetelne wiadomości mają autora i datę.","Sprawdź to w wiarygodnym medium albo na stronach weryfikujących fakty (w Czechach Manipulátoři.cz i Demagog.cz).","Jeśli nie masz pewności, nie przesyłaj wiadomości dalej."],""],"cookies":["Co zrobić z paskiem „cookies” na stronie?","Cookies to małe pliki, dzięki którym strona pamięta, co robisz. Pasek pyta, czy może śledzić Twoje zachowanie w celach reklamowych.",["Spokojnie wybierz „Odrzuć wszystko” lub „Tylko niezbędne”. Strona będzie działać dalej.","Jeśli nie widzisz takiego przycisku, dotknij „Ustawienia” i zostaw włączone tylko „Niezbędne”.","Nie musisz zajmować się paskiem za każdym razem – strona zapamięta Twój wybór."],""],"vir-hlaska":["Na stronie wyskoczyło, że mam wirusa w telefonie","Komunikaty na stronach typu „Twój telefon jest zainfekowany!” to prawie zawsze oszustwo. Chcą Cię przestraszyć, żebyś coś zainstalował lub zapłacił.",["Niczego w oknie nie klikaj i nie dzwoń na wyświetlony numer.","Zamknij kartę lub całą przeglądarkę. W razie potrzeby uruchom telefon ponownie.","Niczego nie instaluj i niczego nie płać.","Jeśli już coś zainstalowałeś lub podałeś kartę, zadzwoń do banku i poproś bliską osobę o pomoc."],""],"mapy":["Jak znaleźć drogę i połączenie w telefonie?","Drogę i połączenia znajdziesz w aplikacjach Mapy.com (dawniej Mapy.cz) lub Mapy Google. Czeskie rozkłady jazdy są na stronie IDOS.",["Otwórz Mapy.com lub Mapy Google i w wyszukiwarce wpisz, dokąd chcesz iść.","Dotknij „Trasa” i wybierz, czy idziesz pieszo, jedziesz samochodem czy komunikacją miejską.","Połączenia autobusowe i kolejowe znajdziesz na stronie idos.cz – wpisz skąd, dokąd i kiedy.","Bilet na pociąg kupisz w aplikacji Můj vlak (Koleje Czeskie) lub w kasie. O zniżki dla seniorów zapytaj w kasie."],""],"objednat-lekar":["Jak umówić się do lekarza przez internet?","Wiele gabinetów oferuje zapisy przez internet lub e-mail. Każdy korzysta jednak z innego systemu, dlatego najpierw zapytaj w gabinecie.",["Zapytaj pielęgniarkę, czy można zapisać się online i pod jakim adresem.","Poproś o zapisanie adresu lub aplikacji na kartce i wpisz go w przeglądarce samodzielnie.","Wybierz termin i potwierdź go. Zwykle dostaniesz potwierdzenie e-mailem lub SMS-em.","Jeśli zapisy online Ci nie odpowiadają, telefon do gabinetu jest nadal w porządku."],"Na pytania o zdrowie i leki odpowie lekarz lub farmaceuta."],"erecept":["Jak działa e-recepta (eRecept)?","eRecept to elektroniczna recepta. Lekarz wyśle Ci ją SMS-em lub e-mailem albo wydrukuje.",["Poczekaj na SMS lub e-mail od lekarza z kodem recepty.","W aptece pokaż wiadomość z kodem (lub wydrukowaną kartkę).","Farmaceuta odczyta kod i wyda Ci lek.","Kod możesz też wysłać bliskiej osobie, która odbierze lek za Ciebie."],"Na pytania o leki, dawkowanie i zdrowie odpowiada lekarz lub farmaceuta, nie DIGI parťák."],"identita":["Jak załatwiać sprawy w czeskich urzędach przez internet?","Wiele spraw z czeskimi urzędami załatwisz na Portalu Obywatela (Portál občana). Zalogujesz się np. tożsamością bankową – tak jak do bankowości internetowej.",["Adres Portalu Obywatela wpisz w przeglądarce sam: obcan.portal.gov.cz.","Wybierz logowanie przez swój bank (tożsamość bankowa) lub inną oferowaną możliwość.","Jeśli nie masz pewności, poproś o pomoc bliską osobę lub pracownika Czech POINT na poczcie czy w urzędzie."],"Nie korzystaj z linków do „urzędu” w SMS-ach lub e-mailach – adres zawsze wpisuj sam."],"cisla":["Jakie są ważne numery telefonów?","Oto najważniejsze numery. Dotknij dowolnego, aby od razu zadzwonić.",[],""],"samota":["Jest mi smutno i czuję się samotny","Przykro mi. Takie uczucia są całkowicie normalne i nie musisz być z nimi sam. Na tych bezpłatnych liniach chętnie Cię wysłuchają (po czesku).",[],""],"krize":["Jest mi naprawdę źle i nie wiem, co robić","Bardzo mi przykro, że tak się czujesz. Proszę, porozmawiaj z kimś teraz. Jesteś ważny.",["Zadzwoń na Linię pierwszej pomocy psychologicznej 116 123 – bezpłatnie i całodobowo (po czesku).","Jeśli jesteś w niebezpieczeństwie, dzwoń pod 112 lub 155.","Możesz też zadzwonić do bliskiej osoby i poprosić, żeby przyszła."],""],"zdravi-nouze":["Problemy zdrowotne – wezwij pomoc","To może być poważne. Proszę, od razu zadzwoń na pogotowie 155 lub na numer alarmowy 112.",["Zadzwoń pod 155 lub 112.","Powiedz, gdzie jesteś i co się dzieje.","Jeśli to możliwe, otwórz drzwi i zadzwoń do sąsiada lub bliskiej osoby."],""],"mimo-zdravi":["Pytania o zdrowie i leki","Na pytania o zdrowie i leki bezpiecznie odpowie tylko lekarz lub farmaceuta. Nie chcę udzielić nieprecyzyjnej porady.",["Zadzwoń do swojego lekarza rodzinnego.","Zapytaj w aptece – farmaceuci chętnie doradzą za darmo.","Przy nagłych dolegliwościach dzwoń pod 155."],""],"mimo-finance":["Porady finansowe i prawne","Nie udzielam porad finansowych ani prawnych – mógłbym niechcący zaszkodzić. Zwróć się proszę do specjalisty.",["O pieniądzach porozmawiaj osobiście w swoim banku.","W sprawach prawnych pomagają bezpłatne poradnie, np. przez Senior telefon (po czesku).","Jeśli ktoś naciska i pogania Cię do podpisania umowy, niczego nie podpisuj."],""],"pozdrav":["Powitanie","Dzień dobry, miło Cię widzieć! Jestem DIGI parťák. Pomogę z telefonem, internetem i bezpieczeństwem w sieci. O co chcesz zapytać?",[],""],"dekuji":["Podziękowanie","Nie ma za co! Jestem tu, kiedy tylko zechcesz. Żadne pytanie nie jest głupie.",[],""],"kdo-jsi":["Kim jest DIGI parťák?","Jestem DIGI parťák – cyfrowy pomocnik, nie człowiek. Najpierw odpowiadam z biblioteki sprawdzonych porad. Jeśli tam nie ma odpowiedzi, spróbuję pomóc za pomocą sztucznej inteligencji i zawsze przypomnę, żeby to sprawdzić.",["Pomogę z telefonem i aplikacjami.","Pomogę rozpoznać fałszywe wiadomości i połączenia.","Pokażę, gdzie zadzwonić po pomoc."],""]},"guides":{"pismo":["Powiększ tekst w telefonie","Większy tekst łatwiej się czyta i oszczędza oczy. Nic się nie zepsuje – w każdej chwili możesz to cofnąć.",[["Otwórz Ustawienia","Znajdź na ekranie ikonę koła zębatego z napisem „Ustawienia” i dotknij jej. ||"],["Znajdź pozycję wyświetlacza","Android: dotknij „Wyświetlacz” (w niektórych telefonach „Ułatwienia dostępu”). iPhone: dotknij „Ekran i jasność”.","Możesz też szukać lupą u góry – wpisz „czcionka”."],["Dotknij Rozmiar czcionki","Android: „Rozmiar czcionki” lub „Rozmiar i styl czcionki”. iPhone: „Wielkość tekstu”. ||"],["Przesuń suwak w prawo","Im bardziej w prawo, tym większy tekst. Przykładowy tekst od razu się zmienia, więc zobaczysz efekt. ||"],["Gotowe","Wróć przyciskiem Wstecz lub zamknij Ustawienia. Tekst pozostanie większy w całym telefonie. ||"]]],"whatsapp-fotka":["Wyślij zdjęcie przez WhatsApp","Spraw radość rodzinie. Zdjęcie wyślesz prosto z rozmowy z daną osobą.",[["Otwórz WhatsApp","Dotknij zielonej ikony z białym telefonem w dymku. ||"],["Wybierz osobę","Na liście czatów dotknij imienia osoby, której chcesz wysłać zdjęcie. ||"],["Dotknij spinacza lub +","Ikona jest na dole obok pola do pisania. Na Androidzie to spinacz, na iPhonie znak plus. ||"],["Wybierz zdjęcie","Dotknij „Galeria” (Android) lub „Biblioteka zdjęć” (iPhone), a potem zdjęcia, które chcesz wysłać. ||"],["Wyślij","Dotknij okrągłego zielonego przycisku ze strzałką. Zdjęcie jest w drodze!","Dwa niebieskie znaczki oznaczają, że druga osoba już je obejrzała."]]],"whatsapp-video":["Rozmowa wideo przez WhatsApp","Zobaczcie się z bliskimi, nawet gdy są daleko. Rozmowa przez Wi-Fi nic nie kosztuje.",[["Otwórz WhatsApp","Dotknij zielonej ikony WhatsApp. ||"],["Wybierz osobę","Dotknij imienia osoby, do której chcesz zadzwonić. ||"],["Dotknij kamery","W prawym górnym rogu jest mała ikona kamery. Dotknij jej.","Ikona słuchawki obok to zwykła rozmowa bez obrazu."],["Poczekaj na odebranie","Gdy druga osoba odbierze, zobaczycie się. Trzymaj telefon przed twarzą. ||"],["Zakończ rozmowę","Dotknij czerwonego przycisku ze słuchawką. ||"]]],"podvodna-sms":["Co zrobić z podejrzanym SMS-em","Fałszywe wiadomości dostaje każdy. Ważne jest, by wiedzieć, jak się zachować.",[["Nie spiesz się","Oszuści chcą, żebyś działał od razu. Masz czas. Weź głęboki oddech. ||"],["Nie klikaj w link","Nie dotykaj linku w wiadomości i nie odpowiadaj na nią. ||"],["Sprawdź to inaczej","Jeśli wiadomość twierdzi, że jest od banku, poczty lub urzędu, zadzwoń tam sam na numer z oficjalnej strony lub z karty. ||"],["Usuń wiadomość","Przytrzymaj palec na wiadomości i wybierz „Usuń”. Numer możesz zablokować. ||"],["Już kliknąłeś?","Nic się nie stanie, jeśli niczego nie wypełniłeś. Jeśli podałeś kartę lub hasło, od razu zadzwoń do banku.","Wiadomość możesz sprawdzić w DIGI parťáku w sekcji „Czy to oszustwo?”."]]],"screenshot-android":["Zrzut ekranu na Androidzie","Zrzut ekranu to zdjęcie tego, co masz właśnie na ekranie. Przydaje się np. do sprawdzenia podejrzanej wiadomości.",[["Otwórz to, co chcesz uchwycić","Na przykład podejrzany SMS. Otwórz wiadomość tak, by widać było cały tekst i nadawcę. ||"],["Znajdź dwa przyciski","Z boku telefonu jest przycisk zasilania i przyciski głośności. Potrzebujesz zasilania i dolnego przycisku głośności (ściszania). ||"],["Naciśnij oba naraz","Naciśnij jednocześnie zasilanie i ściszanie. Przytrzymaj tylko chwilę (ok. 1 sekundy) i puść.","Jeśli zamiast tego pojawi się menu wyłączania, puściłeś przyciski za późno. Spróbuj ponownie, szybciej."],["Ekran mignie","Usłyszysz dźwięk lub zobaczysz krótkie mignięcie i mały podgląd na dole. Zrzut jest zapisany. ||"],["Gdzie znajdziesz zrzut","Otwórz aplikację Galeria lub Zdjęcia Google. Zrzut jest wśród najnowszych zdjęć, często w folderze „Zrzuty ekranu”. ||"],["Nie działa?","W niektórych telefonach (np. Samsung) można to zrobić też tak: pociągnij pasek od górnej krawędzi w dół i dotknij „Zrzut ekranu”. Zależy to od producenta.","Zrzut możesz przesłać w DIGI parťáku w sekcji „Czy to oszustwo?”."]]],"screenshot-iphone":["Zrzut ekranu na iPhonie","Zrzut ekranu to zdjęcie tego, co masz właśnie na ekranie. Sposób zależy od tego, czy Twój iPhone ma okrągły przycisk Początek pod ekranem.",[["Otwórz to, co chcesz uchwycić","Na przykład podejrzany SMS. Otwórz wiadomość tak, by widać było cały tekst i nadawcę. ||"],["iPhone BEZ przycisku Początek","Nowsze iPhone'y (ekran do krawędzi): naciśnij jednocześnie przycisk boczny po prawej i przycisk zwiększania głośności po lewej (górny). Od razu puść. ||"],["iPhone Z przyciskiem Początek","Starsze iPhone'y i iPhone SE (okrągły przycisk na dole): naciśnij jednocześnie przycisk Początek i przycisk boczny po prawej (w najstarszych modelach przycisk na górze). ||"],["Ekran mignie","Ekran na chwilę zbieleje, a w lewym dolnym rogu pojawi się mały podgląd. Nie musisz go dotykać – zrzut zapisze się sam.","Jeśli zamiast tego pojawi się suwak „Wyłącz”, trzymałeś przyciski za długo. Dotknij Anuluj i spróbuj szybciej."],["Gdzie znajdziesz zrzut","Otwórz aplikację Zdjęcia. Zrzut jest wśród najnowszych zdjęć i w albumie „Zrzuty ekranu”.","Zrzut możesz przesłać w DIGI parťáku w sekcji „Czy to oszustwo?”."]]],"banka-hovor":["Dzwoni „bank” – co teraz?","Najczęstsze oszustwo na seniorów. Wystarczy zapamiętać jedną zasadę: rozłącz się i zadzwoń sam.",[["Rozłącz się","Gdy ktoś z „banku” lub „policji” dzwoni w sprawie pieniędzy, zakończ rozmowę. Nie musisz przepraszać. ||"],["Niczego nie podawaj","Nikomu nie mów PIN-u, haseł ani kodów z SMS. Bank nigdy o nie nie poprosi. ||"],["Zadzwoń sam","Weź kartę płatniczą i zadzwoń na numer z jej tylnej strony. ||"],["Powiedz, co się stało","Pracownik banku powie Ci, czy Twoje konto jest w porządku. ||"]]],"erecept":["Odbierz e-receptę (eRecept)","Recepta nie musi już być na papierze. Wystarczy kod, który przyśle lekarz.",[["Poczekaj na wiadomość","Lekarz wyśle Ci SMS lub e-mail z kodem recepty. Może go też wydrukować. ||"],["Idź do apteki","Możesz pójść do dowolnej apteki. ||"],["Pokaż kod","Otwórz wiadomość od lekarza i pokaż ją farmaceucie albo podyktuj kod. ||"],["Gotowe","Farmaceuta odczyta kod i wyda Ci lek.","Kod możesz przesłać bliskiej osobie, która odbierze lek za Ciebie."]]],"plocha":["DIGI parťák na ekranie głównym","Dodaj pomocnika do ekranu głównego jak aplikację. Potem otworzysz go jednym dotknięciem.",[["Otwórz DIGI parťáka w przeglądarce","Android: w Chrome. iPhone: w Safari. ||"],["Otwórz menu","Android: dotknij trzech kropek w prawym górnym rogu. iPhone: dotknij ikony Udostępnij na dole (kwadrat ze strzałką w górę). ||"],["Dodaj do ekranu głównego","Wybierz „Dodaj do ekranu głównego” lub „Zainstaluj aplikację”. ||"],["Potwierdź","Dotknij „Dodaj”. Na ekranie pojawi się ikona z uśmiechniętym dymkiem. ||"]]]},"phones":{"112":["Numer alarmowy","Każde zagrożenie życia, zdrowia lub mienia. Działa także bez środków na koncie."],"150":["Straż pożarna","Pożar, wyciek gazu, pomoc techniczna."],"155":["Pogotowie ratunkowe","Nagłe problemy zdrowotne, uraz, utrata przytomności."],"158":["Policja Czeska","Oszustwo, kradzież, groźby, podejrzana osoba pod drzwiami."],"senior":["Senior telefon (Život 90)","Bezpłatna linia dla seniorów i ich bliskich. Całodobowo, po czesku."],"elpida":["Linia dla seniorów (Elpida)","Bezpłatna rozmowa, gdy jest Ci smutno lub potrzebujesz porady. Po czesku."],"psych":["Linia pierwszej pomocy psychologicznej","Gdy wszystkiego jest za dużo. Bezpłatnie, całodobowo, po czesku."]},"cats":{"bezpeci":"Bezpieczeństwo w sieci","telefon":"Telefon i aplikacje","internet":"Internet, wiadomości i sieci","penize":"Bank i płatności","urady":"Urzędy i lekarz","pomoc":"Pomoc i wsparcie"},"urgent":{"krize":["nie chcę żyć","nie chce zyc","zabić się","zabic sie","samobójstw","skrzywdzić siebie","nie ma sensu żyć"],"zdravi-nouze":["ból w klatce","boli mnie w klatce","nie mogę oddychać","nie moge oddychac","zawał","udar","nieprzytomn","zemdlał","upadł i nie może wstać","krwawi"],"uz-jsem-zadal":["podałem kartę","podałam kartę","kliknąłem w link","kliknęłam w link","wysłałem pieniądze","wysłałam pieniądze","zostałem oszukany","zostałam oszukana","ukradli mi pieniądze"],"banka-vola":["bezpieczne konto","dzwoni bank","dział bezpieczeństwa banku","przelać pieniądze"]},"scam":{"card":"numer karty|dane karty|cvv|pin|hasło|dane logowania|kod weryfikacyjny|kod sms|kod blik|blik","urgent":"natychmiast|pilne|pilnie|w ciągu 24|w ciągu 48|ostatnie wezwanie|ostatnie ostrzeżenie|dzisiaj|wygaśnie|zablokowan|zawieszon|dezaktywowan","fee":"opłat|dopłat|cło|zapłać|uiść|należność|płatność","parcel":"paczk|przesyłk|dostaw|kurier|poczta|inpost|dpd|dhl","bank":"bank|konto|policj|urząd skarbowy|komornik","safeacc":"bezpieczne konto|bezpiecznego konta|przelej|przelać pieniądze","prize":"wygra|wygrał|zwycięzc|gratulacje|nagrod|prezent|za darmo|wybran","family":"cześć mamo|hej mamo|cześć tato|cześć babciu|cześć dziadku|nowy numer|zgubiłem telefon|zepsuł mi się telefon|wyślij mi pieniądze","money":"pieniądze|pieniędzy|wyślij|przelew|przelej|pożycz","remote":"anydesk|teamviewer|rustdesk|zdalny dostęp|zainstaluj aplikację|pobierz aplikację","invest":"inwestycj|inwestuj|krypto|bitcoin|zysk|gwarantowan|wzbogac|dochód pasywny"}};
